DELETE FROM TBL_QPS_STAT
 WHERE HOSP_CD = #{hospCd} AND INDI_CD = #{indiCd}
   AND ( PRD_KEY = #{prdKey}
         OR ( PRD_GB = 'M' AND PRD_KEY IN
              #{mm} ) )

