INSERT INTO TBL_QPS_APPR_LINE (HOSP_CD, STEP_NO, STEP_NM, USE_YN, REG_USER)
VALUES (#{hospCd}, #{stepNo}, #{stepNm}, 'Y', #{regUser})
ON DUPLICATE KEY UPDATE STEP_NM=VALUES(STEP_NM), USE_YN='Y', UPD_USER=#{regUser}

INSERT INTO TBL_QPS_REPORT (HOSP_CD, INDI_CD, PRD_GB, PRD_KEY, STATUS, CUR_STEP, REG_USER)
VALUES (#{hospCd}, #{indiCd}, #{prdGb}, #{prdKey}, #{status}, #{curStep}, #{updUser})
ON DUPLICATE KEY UPDATE STATUS=VALUES(STATUS), CUR_STEP=VALUES(CUR_STEP), UPD_USER=#{updUser}

INSERT INTO TBL_QPS_MGR (HOSP_CD, USER_ID, USE_YN, REG_USER)
VALUES (#{hospCd}, #{userId}, 'Y', #{regUser})
ON DUPLICATE KEY UPDATE USE_YN='Y', UPD_USER=#{regUser}

mapper.update:
UPDATE TBL_QPS_SRVIMPR SET
  IN_YEAR = #{inYear}, DEPT_NM = #{deptNm}, TYPE_NM = #{typeNm}, TOPIC = #{topic},
  PROBLEM = #{problem}, ANALYSIS = #{analysis}, PLAN_TXT = #{planTxt},
  IMPR_DT = REPLACE(#{imprDt},'-',''), RPT_DT = REPLACE(#{rptDt},'-',''), UPD_USER = #{regUser}
 WHERE IMPR_SEQ = #{imprSeq} AND HOSP_CD = #{hospCd}

UPDATE TBL_QPS_SURVEY_ANS
   SET ANS_NO=#{ansno}, WRITER_CD=#{writercd}, SEX_CD=#{sexcd},
       AGE_CD=#{agecd}, ETC_OPN=#{etcopn}
 WHERE ANS_ID=#{ansId} AND HOSP_CD=#{hospCd}
